import React, { useState } from "react";

function App() {
  const [file, setFile] = useState(null);
  const [files, setFiles] = useState([]);

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleUpload = () => {
    if (!file) return;

    const previewUrl = URL.createObjectURL(file);

    const newFile = {
      id: Date.now(),
      name: file.name,
      size: file.size,
      type: file.type,
      preview: previewUrl,
      progress: 0,
    };

    setFiles((prev) => [...prev, newFile]);

    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      setFiles((prev) =>
        prev.map((f) => (f.id === newFile.id ? { ...f, progress } : f))
      );
      if (progress >= 100) clearInterval(interval);
    }, 200);

    setFile(null);
  };

  const handleDelete = (id) => {
    setFiles((prev) => prev.filter((f) => f.id !== id));
  };

  return (
    <div style={{ padding: 20, fontFamily: "Arial" }}>
      <h2>📤 File Sharing (Frontend Only)</h2>

      <input type="file" onChange={handleFileChange} />
      <button onClick={handleUpload} disabled={!file}>
        Upload
      </button>

      <h3>📂 Files</h3>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
          gap: "20px",
        }}
      >
        {files.map((f) => (
          <div
            key={f.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "10px",
              padding: "10px",
              textAlign: "center",
              background: "#fafafa",
              boxShadow: "0 2px 5px rgba(0,0,0,0.1)",
            }}
          >
            <p style={{ fontWeight: "bold" }}>{f.name}</p>
            <p style={{ fontSize: "12px", color: "#555" }}>
              {(f.size / 1024).toFixed(1)} KB
            </p>

            {/* Progress bar */}
            <div
              style={{
                width: "100%",
                height: "8px",
                background: "#eee",
                borderRadius: "5px",
                overflow: "hidden",
                marginBottom: "10px",
              }}
            >
              <div
                style={{
                  width: `${f.progress}%`,
                  height: "100%",
                  background: f.progress < 100 ? "#2196f3" : "green",
                  transition: "width 0.2s ease",
                }}
              ></div>
            </div>
            <p style={{ fontSize: "12px" }}>{f.progress}%</p>

            {/* Previews */}
            {f.type.startsWith("image/") && (
              <img
                src={f.preview}
                alt={f.name}
                style={{
                  width: "100%",
                  height: "120px",
                  objectFit: "cover",
                  borderRadius: "6px",
                  marginBottom: "10px",
                }}
              />
            )}

            {f.type === "application/pdf" && (
              <iframe
                src={f.preview}
                title={f.name}
                style={{
                  width: "100%",
                  height: "120px",
                  border: "1px solid #ccc",
                  marginBottom: "10px",
                }}
              />
            )}

            {!f.type.startsWith("image/") && f.type !== "application/pdf" && (
              <a href={f.preview} download={f.name}>
                Download {f.name}
              </a>
            )}

            <button
              onClick={() => handleDelete(f.id)}
              style={{
                marginTop: "10px",
                padding: "5px 10px",
                background: "red",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer",
              }}
            >
              ❌ Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
